mapper.update:
UPDATE reservations 
SET status = 'CANCELLED' 
WHERE reservation_id = #{reservation_id} AND user_id = #{user_id}

UPDATE reservations r
SET r.status = #{status}
WHERE r.reservation_id = #{reservation_id}
  AND EXISTS (
      SELECT 1 FROM properties p 
      WHERE p.property_id = r.property_id 
        AND p.agent_id = #{agent_id}
  )

mapper.select:
SELECT reservation_id, property_id, user_id, reservation_date, status, created_at
FROM reservations
WHERE reservation_id = #{reservationId}
